jsonTools.init:
function init(bundle) {
  if (window._eliAdminTelemetryInspectorBooted) return;
  window._eliAdminTelemetryInspectorBooted = true;
  if (!eli || !eli.storage || !eli.ui || !eli.register) return;

  var STORE_CONFIG = "config";
  var ROW_PREFIX = "_telemetry_";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // 2026-05-19 v2: pretty tool names. Maps raw stat-key / tool-id
  // forms (snake_case, appOpenedX, single words) to the friendly
  // names users actually recognise. Falls back to title-case for
  // anything not in the table.
  var _TOOL_NAME_MAP = {
    risk: "Legal Risks",
    legal_risks: "Legal Risks",
    draft: "Build Draft",
    build_draft: "Build Draft",
    legal_review: "Legal Review",
    review_redlines: "Review Redlines",
    error_review: "Error Review",
    compare: "Compare",
    docuscrub: "Docuscrub",
    final_review: "Final Review",
    email_helper: "Email Helper",
    auto_emailer: "Email Generator",
    redline_email_pack: "Redline Email Pack",
    redline_authors: "Redline Authors",
    ask_eli: "Ask ELI",
    eli5: "ELI5 Explainer",
    eli5_explanations: "ELI5 Explanations",
    trophy_gallery: "Trophy Gallery",
    playbook_manager: "Playbook Manager",
    risk_rules_manager: "Risk Rules Manager",
    tool_manager: "Tool Manager",
    version_history: "Version History",
    refresh_eli: "Refresh ELI",
    eli_settings: "Settings",
    eli_telemetry: "Telemetry",
    eli_stats: "Stats Engine",
    eli_agent: "ELI Agent",
    bd_template_tester: "Template Tester",
    admin_library_publisher: "Library Publisher",
    admin_data_editor: "Data Editor",
    admin_template_studio: "Template Studio",
    admin_storage_inspector: "Storage Inspector",
    admin_team_guidance: "Team Guidance",
    admin_telemetry_inspector: "User Stats",
    admin_usage_viewer: "Usage Dashboard",
    tool_author_studio: "Tool Author Studio",
    usage_risks: "Usage Risks",
    focus_flow: "Focus Flow",
  };
  function _displayToolName(raw) {
    if (!raw) return "—";
    var s = String(raw).replace(/^appOpened/, "");
    var snake = s.replace(/([A-Z])/g, "_$1").replace(/^_/, "").toLowerCase();
    if (_TOOL_NAME_MAP[snake]) return _TOOL_NAME_MAP[snake];
    // Fallback: title-case the underscore-split.
    return snake.split("_").map(function (p) {
      return p ? p.charAt(0).toUpperCase() + p.slice(1) : "";
    }).join(" ").trim() || "—";
  }
  function _fmtTimeHM(ms) {
    if (!ms) return "—";
    try {
      var d = new Date(ms);
      var h = d.getHours();
      var m = d.getMinutes();
      var ap = h >= 12 ? "pm" : "am";
      var h12 = h % 12; if (h12 === 0) h12 = 12;
      return h12 + ":" + (m < 10 ? "0" + m : m) + ap;
    } catch (e) { return String(ms); }
  }
  function _fmtDateLong(iso) {
    if (!iso) return "—";
    var parts = String(iso).split("-");
    if (parts.length !== 3) return iso;
    var monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    var weekdayNames = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
    try {
      var d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
      return {
        weekday: weekdayNames[d.getDay()],
        month: monthNames[d.getMonth()],
        day: d.getDate(),
        year: d.getFullYear(),
      };
    } catch (e) { return iso; }
  }
  function _isToday(iso) {
    var today = new Date().toISOString().slice(0, 10);
    return iso === today;
  }
  function _fmtCost(usd) {
    var n = Number(usd || 0);
    if (!n) return "$0";
    if (n < 0.01) return "$" + n.toFixed(4);
    return "$" + n.toFixed(2);
  }
  function _fmtTokens(n) {
    n = Number(n) || 0;
    if (n < 1000) return String(n);
    if (n < 1000000) return (n / 1000).toFixed(1).replace(/\.0$/, "") + "k";
    return (n / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  }
  // Inline price table — matches eli_telemetry/engine.js etPriceTable.
  // Replicated so the inspector doesn't need a cross-tool dependency.
  function _estCost(tokensMap) {
    var prices = {
      "gemini-3.1-flash-lite-preview": { in: 0.04, out: 0.20 },
      "gemini-3.1-flash":              { in: 0.075, out: 0.30 },
      "gemini-2.5-flash":              { in: 0.075, out: 0.30 },
      "gemini-2.5-flash-lite-preview": { in: 0.04, out: 0.20 },
      "gemini-2.5-pro":                { in: 1.25, out: 5.00 },
      "gemini-1.5-pro":                { in: 1.25, out: 5.00 },
      "gemini-1.5-flash":              { in: 0.075, out: 0.30 },
      "_default":                      { in: 0.075, out: 0.30 },
    };
    if (!tokensMap || typeof tokensMap !== "object") return 0;
    var total = 0;
    Object.keys(tokensMap).forEach(function (model) {
      var t = tokensMap[model] || {};
      var price = prices[model] || prices._default;
      var inTok = Number(t.promptTokens) || 0;
      var outTok = Number(t.candidatesTokens) || 0;
      total += (inTok * price.in + outTok * price.out) / 1000000;
    });
    return total;
  }

  function _readLocalRows() {
    return eli.storage.getAll(STORE_CONFIG).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf(ROW_PREFIX) === 0;
      }).sort(function (a, b) {
        return String(b.date || "").localeCompare(String(a.date || ""));
      });
    }).catch(function () { return []; });
  }

  function _renderEmpty(mount) {
    mount.innerHTML =
      '<div style="font-family:Inter,system-ui,sans-serif;padding:48px 24px;background:#f8fafc;min-height:100vh;">' +
        '<div style="max-width:720px;margin:0 auto;text-align:center;background:#fff;border:1px solid #e2e8f0;padding:56px 32px;">' +
          '<div style="font-size:42px;margin-bottom:16px;">📊</div>' +
          '<div style="font-family:Georgia,serif;font-size:24px;font-weight:800;color:#0f172a;margin-bottom:8px;letter-spacing:-0.01em;">No activity yet</div>' +
          '<div style="font-size:13px;color:#64748b;line-height:1.55;max-width:420px;margin:0 auto;">Launch any tool and your stats will start populating here — by day, by tool, with AI cost and model usage.</div>' +
        '</div>' +
      '</div>';
  }

  function _render(mount, rows) {
    if (!rows || !rows.length) { _renderEmpty(mount); return; }
    var userKey = rows[0].userKey || "?";
    var userName = rows[0].userName || "?";
    // Doc-wide totals across all days for the inspector header.
    var totalToolsUsed = {};
    var totalCost = 0;
    var totalCalls = 0;
    rows.forEach(function (r) {
      var tu = r.toolsUsed || {};
      Object.keys(tu).forEach(function (k) {
        totalToolsUsed[k] = (totalToolsUsed[k] || 0) + (Number(tu[k]) || 0);
      });
      totalCost += _estCost(r.tokens || {});
      Object.values(r.tokens || {}).forEach(function (m) {
        totalCalls += Number((m && m.calls) || 0);
      });
    });
    var totalLaunchesAllDays = Object.keys(totalToolsUsed).reduce(function (n, k) {
      return n + totalToolsUsed[k];
    }, 0);
    // 2026-05-19 v2: rewrite as a user-grade stats document.
    // Premium framing — Georgia serif headings, slate neutrals, gold
    // accent on hero stat; daily ledger structure where each day card
    // reads at a glance. Keeps every data point: tools, launches,
    // cost, AI calls, models, active window, totals.
    var activeDays = rows.length;
    var maxDayLaunches = 0;
    rows.forEach(function (r) {
      var s = 0;
      Object.values(r.toolsUsed || {}).forEach(function (n) { s += Number(n) || 0; });
      if (s > maxDayLaunches) maxDayLaunches = s;
    });
    var html = '';
    html += '<div style="font-family:Inter,system-ui,sans-serif;background:#f8fafc;min-height:100vh;padding:32px 24px 60px 24px;">';
    html += '<div style="max-width:760px;margin:0 auto;">';
    // ─── HERO / COVER ──────────────────────────────────────────────────
    html += '<div style="background:#fff;border:1px solid #e2e8f0;padding:32px 36px 28px 36px;margin-bottom:24px;">';
    html +=   '<div style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:0.22em;">User Stats</div>';
    html +=   '<div style="font-family:Georgia,serif;font-size:30px;font-weight:800;color:#0f172a;margin-top:4px;letter-spacing:-0.01em;line-height:1.15;">' + _esc(userName) + '</div>';
    html +=   '<div style="display:flex;gap:0;margin-top:22px;border-top:1px solid #e2e8f0;padding-top:18px;flex-wrap:wrap;">';
    function _heroStat(num, lbl, accent) {
      return '<div style="flex:1;min-width:120px;padding:0 16px 0 0;border-right:1px solid #e2e8f0;">' +
        '<div style="font-family:Georgia,serif;font-size:28px;font-weight:800;color:' + (accent || '#0f172a') + ';line-height:1;letter-spacing:-0.01em;font-variant-numeric:tabular-nums;">' + num + '</div>' +
        '<div style="font-size:9.5px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:0.16em;margin-top:8px;">' + lbl + '</div>' +
      '</div>';
    }
    function _heroStatLast(num, lbl, accent) {
      return '<div style="flex:1;min-width:120px;padding:0 0 0 16px;">' +
        '<div style="font-family:Georgia,serif;font-size:28px;font-weight:800;color:' + (accent || '#0f172a') + ';line-height:1;letter-spacing:-0.01em;font-variant-numeric:tabular-nums;">' + num + '</div>' +
        '<div style="font-size:9.5px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:0.16em;margin-top:8px;">' + lbl + '</div>' +
      '</div>';
    }
    html +=     _heroStat(activeDays, "Active Days");
    html +=     _heroStat(totalLaunchesAllDays, "Tool Launches");
    html +=     _heroStat(totalCalls, "AI Calls");
    html +=     _heroStatLast(_fmtCost(totalCost), "Total Spend", "#c9a227");
    html +=   '</div>';
    html += '</div>';
    // ─── PER-DAY LEDGER ────────────────────────────────────────────────
    rows.forEach(function (r) {
      var dayDate = _fmtDateLong(r.date);
      var isToday = _isToday(r.date);
      var tbt = r.tokensByTool || {};
      var unionToolNames = {};
      Object.keys(r.toolsUsed || {}).forEach(function (k) { unionToolNames[k] = true; });
      Object.keys(tbt).forEach(function (k) { if (k !== "_unknown") unionToolNames[k] = true; });
      var toolEntries = Object.keys(unionToolNames).map(function (t) {
        return {
          tool: t,
          count: Number((r.toolsUsed || {})[t]) || 0,
          cost: _estCost(tbt[t] || {}),
        };
      }).sort(function (a, b) {
        if (b.count !== a.count) return b.count - a.count;
        return b.cost - a.cost;
      });
      var dayLaunches = toolEntries.reduce(function (n, e) { return n + e.count; }, 0);
      var dayCost = _estCost(r.tokens || {});
      var dayCalls = Object.values(r.tokens || {}).reduce(function (n, m) {
        return n + Number((m && m.calls) || 0);
      }, 0);
      var maxToolCount = toolEntries.length ? toolEntries[0].count : 1;
      var unkCost = _estCost(tbt._unknown || {});
      // Day card.
      html += '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:20px;' +
              (isToday ? 'border-left:3px solid #c9a227;' : '') + '">';
      // Day header — weekday + month on left, big day number on right.
      html +=   '<div style="display:flex;justify-content:space-between;align-items:flex-start;padding:22px 28px 16px 28px;border-bottom:1px solid #f1f5f9;gap:16px;">';
      html +=     '<div style="min-width:0;">';
      html +=       '<div style="font-size:10px;font-weight:800;color:' + (isToday ? '#c9a227' : '#64748b') + ';text-transform:uppercase;letter-spacing:0.22em;">' + _esc(dayDate.weekday || "") + (isToday ? '  ·  Today' : '') + '</div>';
      html +=       '<div style="font-size:10px;color:#94a3b8;letter-spacing:0.08em;margin-top:2px;">' + _esc((dayDate.month || "") + " " + (dayDate.year || "")) + '</div>';
      // Day-level stat strip
      html +=       '<div style="display:flex;gap:18px;margin-top:14px;font-variant-numeric:tabular-nums;flex-wrap:wrap;">';
      html +=         '<div><span style="font-size:18px;font-weight:800;color:#0f172a;">' + dayLaunches + '</span><span style="font-size:10.5px;color:#64748b;margin-left:5px;">launch' + (dayLaunches === 1 ? '' : 'es') + '</span></div>';
      if (dayCalls > 0) html += '<div><span style="font-size:18px;font-weight:800;color:#0f172a;">' + dayCalls + '</span><span style="font-size:10.5px;color:#64748b;margin-left:5px;">AI call' + (dayCalls === 1 ? '' : 's') + '</span></div>';
      if (dayCost > 0) html += '<div><span style="font-size:18px;font-weight:800;color:#c9a227;">' + _fmtCost(dayCost) + '</span><span style="font-size:10.5px;color:#64748b;margin-left:5px;">spent</span></div>';
      html +=       '</div>';
      // Active window — quiet inline, not a separate bar.
      if (r.firstActiveAt || r.lastActiveAt) {
        html +=     '<div style="font-size:10.5px;color:#94a3b8;margin-top:10px;letter-spacing:0.02em;">Active ' + _fmtTimeHM(r.firstActiveAt) + ' – ' + _fmtTimeHM(r.lastActiveAt) + '</div>';
      }
      html +=     '</div>';
      // Big day number on the right.
      html +=     '<div style="text-align:right;flex-shrink:0;">';
      html +=       '<div style="font-family:Georgia,serif;font-size:46px;font-weight:800;color:#0f172a;line-height:1;letter-spacing:-0.02em;font-variant-numeric:tabular-nums;">' + _esc(dayDate.day || "") + '</div>';
      html +=     '</div>';
      html +=   '</div>';
      // Tool table — labels left, bar fills + counts + cost right.
      if (toolEntries.length === 0 && unkCost <= 0) {
        html += '<div style="padding:18px 28px;font-size:11.5px;color:#94a3b8;font-style:italic;">No activity recorded for this day.</div>';
      } else {
        html += '<div style="padding:14px 28px 4px 28px;">';
        html +=   '<div style="font-size:9.5px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.18em;margin-bottom:10px;">By Tool</div>';
        toolEntries.forEach(function (e) {
          var pct = e.count > 0 ? Math.max(4, Math.round((e.count / maxToolCount) * 100)) : 0;
          html += '<div style="display:flex;align-items:center;gap:14px;padding:7px 0;border-bottom:1px solid #f8fafc;font-variant-numeric:tabular-nums;">';
          html +=   '<div style="flex:1;min-width:0;font-size:13px;color:#0f172a;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + _esc(_displayToolName(e.tool)) + '</div>';
          html +=   '<div style="flex:0 0 110px;height:6px;background:#f1f5f9;position:relative;overflow:hidden;">' +
                      '<div style="position:absolute;inset:0;width:' + pct + '%;background:linear-gradient(90deg,#475569,#0f172a);"></div>' +
                    '</div>';
          html +=   '<div style="flex:0 0 44px;text-align:right;font-size:13px;font-weight:800;color:#0f172a;">' + e.count + '</div>';
          html +=   '<div style="flex:0 0 64px;text-align:right;font-size:12px;font-weight:' + (e.cost > 0 ? '700' : '500') + ';color:' + (e.cost > 0 ? '#0f172a' : '#cbd5e1') + ';font-family:ui-monospace,monospace;">' + (e.cost > 0 ? _fmtCost(e.cost) : '—') + '</div>';
          html += '</div>';
        });
        // Unattributed AI tokens row (when AI fired before any tool launch).
        if (unkCost > 0) {
          html += '<div style="display:flex;align-items:center;gap:14px;padding:7px 0;border-top:1px dashed #fecaca;font-variant-numeric:tabular-nums;">';
          html +=   '<div style="flex:1;min-width:0;font-size:12.5px;color:#991b1b;font-style:italic;font-weight:600;">Unattributed AI</div>';
          html +=   '<div style="flex:0 0 110px;"></div>';
          html +=   '<div style="flex:0 0 44px;text-align:right;font-size:12px;color:#cbd5e1;">—</div>';
          html +=   '<div style="flex:0 0 64px;text-align:right;font-size:12px;font-weight:700;color:#991b1b;font-family:ui-monospace,monospace;">' + _fmtCost(unkCost) + '</div>';
          html += '</div>';
        }
        html += '</div>';
      }
      // Models breakdown — kept as a quieter sub-table at the bottom.
      var tokensMap = r.tokens || {};
      var tokenModels = Object.keys(tokensMap);
      if (tokenModels.length > 0) {
        html += '<div style="padding:14px 28px 22px 28px;border-top:1px solid #f1f5f9;margin-top:6px;">';
        html +=   '<div style="font-size:9.5px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.18em;margin-bottom:10px;">AI Models</div>';
        tokenModels.forEach(function (model) {
          var m = tokensMap[model] || {};
          var modelCost = _estCost({ [model]: m });
          var calls = Number(m.calls) || 0;
          var inTok = Number(m.promptTokens) || 0;
          var outTok = Number(m.candidatesTokens) || 0;
          html += '<div style="display:flex;align-items:baseline;gap:12px;padding:5px 0;font-size:12px;color:#334155;font-variant-numeric:tabular-nums;flex-wrap:wrap;">';
          html +=   '<div style="flex:1;min-width:160px;font-family:ui-monospace,monospace;font-size:11px;color:#334155;">' + _esc(model) + '</div>';
          html +=   '<div style="flex:0 0 auto;color:#64748b;"><strong style="color:#0f172a;">' + calls + '</strong> call' + (calls === 1 ? '' : 's') + '</div>';
          html +=   '<div style="flex:0 0 auto;color:#64748b;">' + _fmtTokens(inTok) + ' <span style="color:#cbd5e1;">→</span> ' + _fmtTokens(outTok) + '</div>';
          html +=   '<div style="flex:0 0 64px;text-align:right;font-weight:700;color:#c9a227;font-family:ui-monospace,monospace;">' + _fmtCost(modelCost) + '</div>';
          html += '</div>';
        });
        html += '</div>';
      }
      html += '</div>'; // day card
    });
    // ─── ACTIONS ───────────────────────────────────────────────────────
    html += '<div style="margin-top:32px;background:#fff;border:1px solid #e2e8f0;padding:18px 22px;">';
    html +=   '<div style="font-size:9.5px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.18em;margin-bottom:10px;">Manage Data</div>';
    html +=   '<div style="display:flex;gap:8px;flex-wrap:wrap;">';
    function _actBtn(id, label, isPrimary, tip) {
      var base = "padding:8px 14px;font-size:11px;font-weight:800;letter-spacing:0.04em;cursor:pointer;border-radius:0;font-family:Inter,system-ui,sans-serif;";
      var style = isPrimary
        ? "background:linear-gradient(180deg,#fef2f2,#fee2e2);border:1px solid #dc2626;color:#991b1b;"
        : "background:#fff;border:1px solid #cbd5e1;color:#475569;";
      return '<button id="' + id + '" type="button" title="' + _esc(tip) + '" style="' + base + style + '">' + _esc(label) + '</button>';
    }
    // 2026-05-19: Reset CDN gated to users who actually have GitHub
    // credentials. Regular users would just hit a "Missing GitHub PAT"
    // toast — better to hide the button entirely than dangle it.
    var _hasGhCreds = (function () {
      try {
        var pat = (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_user_github_pat") || "") : "";
        var repo = (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_github_repo") || "") : "";
        return !!(pat && repo);
      } catch (_e) { return false; }
    })();
    html +=     _actBtn("atiRefresh",   "↻ Refresh",        false, "Re-read your stats");
    html +=     _actBtn("atiResetToday", "Reset Today",     true,  "Clear today's stats");
    html +=     _actBtn("atiResetAll",   "Reset All Days",  true,  "Delete every day from your stats");
    if (_hasGhCreds) {
      html +=   _actBtn("atiResetCdn",   "Reset Cloud",     true,  "Wipe your cloud copy so the next reload starts clean (admin)");
    }
    html +=   '</div>';
    html += '</div>';
    html += '</div>'; // max-width container
    html += '</div>'; // page bg
    mount.innerHTML = html;
    var refreshBtn = mount.querySelector("#atiRefresh");
    if (refreshBtn) {
      refreshBtn.onclick = function () {
        mount.innerHTML = '<div style="padding:40px;text-align:center;color:#64748b;font-family:Inter,system-ui,sans-serif;">Reading IDB…</div>';
        _readLocalRows().then(function (r) { _render(mount, r); });
      };
    }
    // Script Lab iframe blocks native confirm() silently — must use
    // eli.ui.confirm. (Per CLAUDE.md "Forbidden patterns".)
    var resetTodayBtn = mount.querySelector("#atiResetToday");
    if (resetTodayBtn) {
      resetTodayBtn.onclick = function () {
        var today = new Date().toISOString().slice(0, 10);
        var todayRow = rows.find(function (r) { return r.date === today; });
        if (!todayRow) {
          if (typeof showToast === "function") showToast("Nothing recorded for today yet — nothing to reset.", "info");
          return;
        }
        var summary = Object.keys(todayRow.toolsUsed || {})
          .map(function (k) { return _displayToolName(k) + " · " + todayRow.toolsUsed[k]; })
          .join(", ") || "(no activity yet today)";
        eli.ui.confirm({
          title: "Reset today's stats?",
          message:
            "Zero out today's activity.\n\n" +
            "Current: " + summary,
          confirmLabel: "Reset Today",
          danger: true,
        }).then(function (ok) {
          if (!ok) return;
          todayRow.toolsUsed = {};
          todayRow.tokens = {};
          eli.storage.put(STORE_CONFIG, todayRow).then(function () {
            if (typeof showToast === "function") showToast("Today's local counts reset to 0", "ok");
            _readLocalRows().then(function (r) { _render(mount, r); });
          }).catch(function (e) {
            if (typeof showToast === "function") showToast("Reset failed: " + (e && e.message || "unknown"), "err");
          });
        });
      };
    }
    var resetAllBtn = mount.querySelector("#atiResetAll");
    if (resetAllBtn) {
      resetAllBtn.onclick = function () {
        eli.ui.confirm({
          title: "Delete all days?",
          message:
            "Removes every day from your local stats (" + rows.length + " day" +
            (rows.length === 1 ? "" : "s") + ").\n\n" +
            "Your cloud copy is untouched. New activity starts from zero.",
          confirmLabel: "Delete All",
          danger: true,
        }).then(function (ok) {
          if (!ok) return;
          Promise.all(rows.map(function (r) {
            return eli.storage.delete(STORE_CONFIG, r.key).catch(function () {});
          })).then(function () {
            if (typeof showToast === "function") showToast("All local stats deleted", "ok");
            _readLocalRows().then(function (r) { _render(mount, r); });
          });
        });
      };
    }
    // 2026-05-18 v53: Reset CDN — wipes usage/<userKey>.json directly
    // via the GitHub Contents API so the next telemetry boot reads
    // an empty digest and the MAX merge starts from zero. Same PAT
    // path admin_library_publisher uses (eli_user_github_pat /
    // eli_github_repo / eli_github_branch from credentials import).
    var resetCdnBtn = mount.querySelector("#atiResetCdn");
    if (resetCdnBtn) {
      resetCdnBtn.onclick = function () {
        function _lsGet(k) {
          try { return (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet(k) || "") : ""; }
          catch (_e) { return ""; }
        }
        var pat = _lsGet("eli_user_github_pat");
        var repo = _lsGet("eli_github_repo");
        var branch = _lsGet("eli_github_branch") || "main";
        if (!pat || !repo) {
          if (typeof showToast === "function") showToast("Missing GitHub PAT or repo — import credentials via main Settings → Import Credentials first.", "err");
          return;
        }
        var keyForCdn = String((rows[0] && rows[0].userKey) || "").toLowerCase().trim();
        if (!keyForCdn) {
          if (typeof showToast === "function") showToast("No userKey found — can't determine CDN file path.", "err");
          return;
        }
        var filePath = "usage/" + keyForCdn + ".json";
        eli.ui.confirm({
          title: "Reset cloud stats?",
          message:
            "Wipes your cloud copy so the next reload starts fresh.\n\n" +
            "Only affects your own stats — nobody else's.",
          confirmLabel: "Reset Cloud",
          danger: true,
        }).then(function (ok) {
          if (!ok) return;
          resetCdnBtn.disabled = true;
          resetCdnBtn.textContent = "⏳ Wiping…";
          function _strToB64(s) {
            var utf8 = unescape(encodeURIComponent(s));
            return btoa(utf8);
          }
          // GET current SHA so the PUT is a clean update (not a create).
          var getUrl = "https://api.github.com/repos/" + repo + "/contents/" +
            encodeURIComponent(filePath).replace(/%2F/g, "/") +
            "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
          fetch(getUrl, {
            cache: "no-store",
            headers: {
              "Authorization": "Bearer " + pat,
              "Accept": "application/vnd.github+json",
              "X-GitHub-Api-Version": "2022-11-28",
            },
          }).then(function (r) {
            if (r.status === 404) return null;
            if (!r.ok) return r.text().then(function (t) { throw new Error("GET failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
            return r.json();
          }).then(function (existing) {
            var cleared = {
              userName: (rows[0] && rows[0].userName) || keyForCdn.toUpperCase(),
              userKey: keyForCdn,
              generatedAt: new Date().toISOString(),
              days: [],
              note: "Cleared " + new Date().toISOString().slice(0, 10) +
                " via Telemetry Inspector — neutralizes MAX-merge bringing back stale counts.",
            };
            var putUrl = "https://api.github.com/repos/" + repo + "/contents/" +
              encodeURIComponent(filePath).replace(/%2F/g, "/");
            var body = {
              message: "Telemetry Inspector: clear " + filePath,
              content: _strToB64(JSON.stringify(cleared, null, 2) + "\n"),
              branch: branch,
            };
            if (existing && existing.sha) body.sha = existing.sha;
            return fetch(putUrl, {
              method: "PUT",
              headers: {
                "Authorization": "Bearer " + pat,
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
                "Content-Type": "application/json",
              },
              body: JSON.stringify(body),
            }).then(function (r) {
              if (!r.ok) return r.text().then(function (t) { throw new Error("PUT failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
              return r.json();
            });
          }).then(function () {
            // Purge jsdelivr cache so the next telemetry boot sees the
            // cleared file immediately (not the cached old version).
            var purgeUrl = "https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filePath;
            return fetch(purgeUrl).catch(function () { /* tolerate purge failures */ });
          }).then(function () {
            if (typeof showToast === "function") showToast("Cloud stats reset. Reload to start fresh.", "ok");
            resetCdnBtn.disabled = false;
            resetCdnBtn.textContent = "Reset CDN";
          }).catch(function (err) {
            if (typeof showToast === "function") showToast("Cloud reset failed: " + ((err && err.message) || err), "err");
            resetCdnBtn.disabled = false;
            resetCdnBtn.textContent = "Reset CDN";
          });
        });
      };
    }
  }

  function _open() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminTelemetryInspector"); } catch (e) {}
    var out = eli.ui && typeof eli.ui.claimOutput === "function" ? eli.ui.claimOutput() : document.getElementById("output");
    if (!out) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    // Force block layout so the kernel's flex doesn't squish our content.
    var wrap = document.createElement("div");
    wrap.style.cssText = "display:block;width:100%;box-sizing:border-box;";
    out.appendChild(wrap);
    wrap.innerHTML = '<div style="padding:40px;text-align:center;color:#64748b;font-family:Inter,system-ui,sans-serif;">Reading IDB…</div>';
    _readLocalRows().then(function (rows) { _render(wrap, rows); });
  }

  eli.register({
    tile: { app_admin_telemetry_inspector: _open },
    admin_telemetry_inspector: { open: _open },
  });

  eli.log.event("tool", "admin_telemetry_inspector_initialized", {});
}
